import re

session_file = '/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out/play/users/u042/system/state/sessions/01a192d5-189c-714f-9327-875920ae24f3.jsonl'
with open(session_file) as f:
    content = f.read()

match = re.search(r'Test input \(24x24\):', content)
if match:
    rest = content[match.end():]

    # Get first 24 valid grid rows
    lines = rest.split('\\n')
    grid_rows = []
    for line in lines:
        stripped = line.strip()
        if stripped and re.match(r'^\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+', stripped):
            tokens = stripped.split()
            if len(tokens) == 24:
                grid_rows.append(stripped)
                if len(grid_rows) >= 24:
                    break

    print(f"Extracted {len(grid_rows)} rows")

    # Convert to 2D array
    grid = [[int(x) for x in row.split()] for row in grid_rows]
    print(f"Grid shape: {len(grid)}x{len(grid[0])}")

    # Analyze colors in each cell
    from collections import Counter
    non_bg = [v for row in grid for v in row if v not in [0, 5]]
    print(f"\nColors: {Counter(non_bg)}")

    print("\nColored cells (row, col, color):")
    for r in range(5):
        for c in range(5):
            found_color = None
            for dy in range(4):
                for dx in range(4):
                    y, x = r*5 + dy, c*5 + dx
                    if grid[y][x] not in [0, 5]:
                        found_color = grid[y][x]
                        break
                if found_color:
                    break
            if found_color:
                print(f"  Cell({r},{c}) = {found_color}")

    # Print pattern for each row of cells
    print("\nDistribution by cell row:")
    for r in range(5):
        row_pattern = ""
        for c in range(5):
            found_color = None
            for dy in range(4):
                for dx in range(4):
                    y, x = r*5 + dy, c*5 + dx
                    if grid[y][x] not in [0, 5]:
                        found_color = grid[y][x]
                        break
                if found_color:
                    break
            row_pattern += f"{found_color if found_color else '.'} "
        print(f"  {row_pattern}")

